algorithms.pseudocode:
for r in 0 .. num_logical_regs - 1:
  if sR_RegTable[r].decay_ctr > 0:
    sR_RegTable[r].decay_ctr = sR_RegTable[r].decay_ctr - 1
  elif sR_RegTable[r].decay_ctr == 0:
    sR_RegTable[r].valid = 0

if instruction.has_dest_reg:
  reg = instruction.dest_reg
  sR_RegTable[reg].valid = 0
  sR_RegTable[reg].payload = instruction.rob_index

if instruction.has_dest_reg:
  reg = instruction.dest_reg
  if sR_RegTable[reg].valid == 0 and sR_RegTable[reg].payload == instruction.rob_index:
    val = instruction.result_value
    if instruction.is_int:
      trailing = min(count_trailing_zeros(val), 63)
      leading = min(count_leading_zeros(val), 63)
      val6 = val & 0x3F
      digest = (trailing & 0x3F) ^ ((leading & 0x3F) << 3) ^ (val6 << 6)
    else if instruction.is_fp:
      digest = extract_fp_sign_and_exp(val) << 3
    else if instruction.is_flag:
      val4 = val & 0xF
      digest = val4 | (val4 << 4) | (val4 << 8)
    else:
      digest = 0

    sR_RegTable[reg].payload = digest & 0xFFF
    sR_RegTable[reg].valid = 1
    sR_RegTable[reg].decay_ctr = (1 << decay_ctr_bits) - 1

for r in 0 .. num_logical_regs - 1:
  if sR_RegTable[r].valid == 0:
    if instruction_is_squashed(sR_RegTable[r].payload):
      sR_RegTable[r].payload = 0

if format == FP16:
  return val[15:13]
else if format == FP32:
  return val[31:26]
else if format == FP64:
  return val[63:55]
else:
  return 0
